class Solution {
    func isSolvable(_ words: [String], _ result: String) -> Bool {
        // Extract all unique characters
        var uniqueCharsSet = Set<Character>()
        for word in words {
            for ch in word {
                uniqueCharsSet.insert(ch)
            }
        }
        for ch in result {
            uniqueCharsSet.insert(ch)
        }
        let uniqueChars = Array(uniqueCharsSet)
        if uniqueChars.count > 10 { return false } // more than digits available

        // Leading characters cannot be zero
        var leadingChars = Set<Character>()
        for word in words {
            if let first = word.first {
                leadingChars.insert(first)
            }
        }
        if let first = result.first {
            leadingChars.insert(first)
        }

        // Precompute the positional weights for each character
        // sum of words - result = 0
        // For each character, compute sum of (count * 10^pos) in words minus in result
        // Then the equation becomes sum(charValue * weight) == 0
        var charWeights = [Character: Int]()

        func addWeights(_ word: String, sign: Int) {
            let n = word.count
            for (i, ch) in word.enumerated() {
                let power = n - i - 1
                charWeights[ch, default: 0] += sign * Int(pow(10.0, Double(power)))
            }
        }

        for word in words {
            addWeights(word, sign: 1)
        }
        addWeights(result, sign: -1)

        // Backtracking to assign digits to characters
        var charToDigit = [Character: Int]()
        var usedDigits = [Bool](repeating: false, count: 10)

        func backtrack(_ index: Int, _ currentSum: Int) -> Bool {
            if index == uniqueChars.count {
                return currentSum == 0
            }
            let ch = uniqueChars[index]
            let weight = charWeights[ch]!

            for digit in 0...9 {
                if usedDigits[digit] {
                    continue
                }
                // Leading character cannot be zero
                if digit == 0 && leadingChars.contains(ch) {
                    continue
                }
                charToDigit[ch] = digit
                usedDigits[digit] = true

                // Update currentSum
                let newSum = currentSum + weight * digit
                // Prune: if at last char, newSum must be zero
                // No pruning here because we check at the end

                if backtrack(index + 1, newSum) {
                    return true
                }

                usedDigits[digit] = false
                charToDigit[ch] = nil
            }
            return false
        }

        return backtrack(0, 0)
    }
}

